"""Derive SkyyHud/build_skyyhud_0.3.28.py from the LIVE SkyyHud 0.3.27 (build_skyyhud_0.3.27.py = the tools/deploy_set.py SET pin, generated by
tools/hud_0_3_27_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change is undone on a
copy and compared with 0.3.27 (nothing else changed). Line endings kept.
Run:  python tools/hud_0_3_28_patch.py   then   python SkyyHud/build_skyyhud_0.3.28.py   (never --deploy)
Check: python SkyyHud/test_skyyhud_0.3.28.py [--dir <folder inside tools/dev/scratch/>] [--keep]

0.3.28 (2026-10-16) = HUD widget Background OFF by default. Skyy 2026-10-16 (screenshot of the Abilities widget settings): "and lets do
background off by default." Popup "Background OFF by default for which HUD widgets?" -> "all but quest tracker." (docs/answered/ui.md).
  - Widgets.def(id) (the built-in layout of every widget) now starts with Background OFF for every widget except Quest (the Quest Tracker),
    which keeps Background ON. The 0.3.27 built-in layout is kept as Widgets.def0(id); def(id) = def0(id) + bg = Widgets.bgDef(id)
    (true only for "Quest"). The unknown-id fallback is OFF too.
  - Where the default reaches: a player with NO layout file (never changed the HUD), a widget missing from an older layout file, and
    /skyyhud reset (= Widgets.start, which is def(id) unless the admin set a server default layout).
  - Saved data untouched: WLayout.ser() writes the Background field of EVERY widget on every save (field 6, "1" / "0"), so a saved file
    cannot tell a chosen ON from the old default ON - player layout files, layout profiles, export codes and the admin's server default
    layout (Server Setup -> HUD -> default layout, an explicit code) are read exactly as before and never rewritten. No migration, no
    config row (there is no server-side Background setting). WLayout's constructor still starts at bg = true, so a pre-0.3.6 five-field
    line / code still reads Background ON as it always did.
  - Unchanged: the Settings page Background ON / OFF row, "Reset style" (never touched Background), every draw path (l.bg), commands,
    permissions, the file format. ROLLBACK to 0.3.27: safe (same file format; players without a file get Background ON again).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.27.py")
dst = os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.28.py")
raw = open(src, encoding="utf8", newline="").read()
CR, LF = chr(13), chr(10)
NL = CR + LF if (CR + LF) in raw else LF
s = raw.replace(CR + LF, LF)
OLD = s
assert 'VERSION = "0.3.27"' in s and "GENERATED by tools/hud_0_3_27_patch.py from the LIVE 0.3.26" in s and "bgDef" not in s, "not the 0.3.27 script"
CHANGES = []


def rep(old, new):
    global s
    n = s.count(old)
    assert n == 1, "anchor count %d: %s" % (n, old[:160])
    s = s.replace(old, new, 1)
    CHANGES.append((new, old))


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.28 (2026-10-16)"):].rstrip() + "\n"

# ================================================================================================ docstring + version
rep('''"""SkyyHud 0.3.27 - build script (javassist via jpype). GENERATED by tools/hud_0_3_27_patch.py from the LIVE 0.3.26 - edit the patch.
Run:   python build_skyyhud_0.3.27.py            -> SkyyHud/SkyyHud-0.3.27.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.27.py
''', '''"""SkyyHud 0.3.28 - build script (javassist via jpype). GENERATED by tools/hud_0_3_28_patch.py from the LIVE 0.3.27 - edit the patch.
Run:   python build_skyyhud_0.3.28.py            -> SkyyHud/SkyyHud-0.3.28.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.28.py
''' + NOTE + '''0.3.27 (generated by tools/hud_0_3_27_patch.py from 0.3.26):
''')
rep('VERSION = "0.3.27"\n', 'VERSION = "0.3.28"\n')

# ================================================================================================ the one table: Background ON by default
rep('''IDS.append("Quest")
''', '''IDS.append("Quest")
# 0.3.28 (Skyy 2026-10-16: "all but quest tracker."): the widgets whose built-in layout starts with Background ON - every other one is OFF
BG_ON = ["Quest"]
''')

# ================================================================================================ Widgets.def = the 0.3.27 layout (def0) + the default Background
rep('''def_lines = "\\n".join(_def_line(i, d) for i, d in DEFAULTS.items())
wid.addMethod(CtNewMethod.make(f"""
public static {PKG}.WLayout def(String id) {{
{def_lines}
  return new {PKG}.WLayout(false, "tl", 8, 8, 100);
}}""", wid))
''', '''def_lines = "\\n".join(_def_line(i, d) for i, d in DEFAULTS.items())
wid.addMethod(CtNewMethod.make(f"""
public static {PKG}.WLayout def0(String id) {{
{def_lines}
  return new {PKG}.WLayout(false, "tl", 8, 8, 100);
}}""", wid))
# 0.3.28: Background OFF by default for every widget except BG_ON (the Quest Tracker); a saved layout line always carries its own value
assert BG_ON and all(i in IDS for i in BG_ON), BG_ON
wid.addMethod(CtNewMethod.make("""
public static boolean bgDef(String id) {
%s
  return false;
}""" % "\\n".join('  if ("%s".equals(id)) return true;' % i for i in BG_ON), wid))
wid.addMethod(CtNewMethod.make(f"""
public static {PKG}.WLayout def(String id) {{
  {PKG}.WLayout w = def0(id);
  w.bg = bgDef(id);
  return w;
}}""", wid))
''')

# ================================================================================================ checks on the result
_i = s.index
assert _i("public static {PKG}.WLayout def0(String id)") < _i("public static boolean bgDef(String id)") < _i("public static {PKG}.WLayout def(String id)") < _i("public static {PKG}.WLayout start(String id)")
assert s.count("this.bg = true;") == 1, "WLayout's constructor still starts at bg = true (old five-field lines read ON)"

# ================================================================================================ done
_u = s
for _new, _old in reversed(CHANGES):
    assert _u.count(_new) == 1, "a change is not unique any more: %s" % _new[:100]
    _u = _u.replace(_new, _old, 1)
assert _u == OLD, "the generated script differs from 0.3.27 outside the recorded changes"
compile(s, dst, "exec")
open(dst, "w", encoding="utf8", newline="").write(s.replace(LF, NL) if NL != LF else s)
print("wrote", os.path.relpath(dst, ROOT), "(%d lines; 0.3.27 had %d; %d changes)" % (s.count(LF), OLD.count(LF), len(CHANGES)))
